solution:
def shorten(roots: list[str], sentence: str) -> str:
    trie = {}
    for root in roots:
        node = trie
        for ch in root:
            node = node.setdefault(ch, {})
        node["$"] = True                 # a whole root ends here

    def shortest_root(word: str) -> str:
        node = trie
        for i, ch in enumerate(word):
            if ch not in node:
                break                    # no root continues along this word
            node = node[ch]
            if "$" in node:
                return word[:i + 1]      # first end mark on the way down = shortest root
        return word

    return " ".join(shortest_root(w) for w in sentence.split(" "))

perf.naive:
def shorten(roots: list[str], sentence: str) -> str:
    words = sentence.split(" ")
    for i, word in enumerate(words):
        for root in roots:                       # try every root against every word
            if word.startswith(root) and len(root) < len(words[i]):
                words[i] = root
    return " ".join(words)
